"use client";

import Link from "next/link";

import { config } from "@/config";
import { useAttribution } from "@/analytics/store";
import { banner } from "@/data/content/banner";
import { format } from "@/lib/format";

/**
 * FR-15 — the 5% QR discount banner.
 *
 * Rendered server-side on `/l/*` so it is present in the initial viewport with
 * zero layout shift (C-8: the *code* is never SSR'd — the server renders an
 * empty slot — it is filled from the attribution store after the client mints
 * it). On other routes it is injected by `BannerInjector`, and only for
 * sessions whose cookie says `ref: "qr"` — an organic visitor never gets this
 * element in their DOM at all.
 *
 * Copy lives in `src/data/content/banner.ts` (NFR-8); the percentage is
 * interpolated there and here via `format()`, never string-concatenated.
 */
export function DiscountBanner() {
  const attr = useAttribution();
  const code = attr?.code ?? "";
  const headline = format(banner.headline, {
    percent: config.NEXT_PUBLIC_DISCOUNT_PERCENT,
  });

  return (
    <aside
      data-discount-banner
      aria-label={banner.ariaLabel}
      className="rounded-xl border border-emerald-300/70 bg-emerald-50 px-4 py-3 text-emerald-950 shadow-sm dark:border-emerald-700/70 dark:bg-emerald-950 dark:text-emerald-50"
    >
      <div className="flex flex-wrap items-center gap-x-4 gap-y-2">
        <p className="text-sm font-medium">{headline}</p>

        <p className="text-sm">
          {banner.codeLabel}{" "}
          <span
            role="status"
            data-discount-code
            className="rounded bg-white/70 px-1.5 py-0.5 font-mono text-xs font-semibold tracking-wide dark:bg-black/40"
          >
            {code || "\u00a0"}
          </span>
        </p>

        <Link
          href="/offer"
          className="ml-auto text-sm font-medium underline underline-offset-2 hover:opacity-80"
        >
          {banner.termsLink}
        </Link>
      </div>
    </aside>
  );
}
