/**
 * Copy helpers for NFR-8 — "i18n-ready string externalisation" (architect
 * spec §11.4: *all* user-facing strings live in `src/data/content/*.ts`, and
 * date/copy formatting goes through `Intl`, never hand-rolled).
 *
 * Content modules hold plain `{ key: string }` values so a future locale is a
 * new file rather than a refactor (plan T13). Anything needing a runtime value
 * — a configured percentage, an expiry date — carries a `{placeholder}` that is
 * interpolated *here*, never by concatenating fragments in a component: word
 * order differs between languages, so "You're getting" + value + "off" cannot
 * be reassembled by a translator.
 *
 * Framework-free by design: this file is part of `src/lib/**`, which must not
 * import React, Next.js or the DOM (architect spec §6 / AD-2).
 */

/** Values substituted into a copy template. */
export type CopyParams = Record<string, string | number>;

/**
 * BCP-47 tag for the single language shipping at launch (NFR-8 — one locale,
 * structure ready for more). Switching locale is a change of *this* default
 * plus a new content file; no component edits.
 */
export const DEFAULT_LOCALE = "en-GB";

const PLACEHOLDER = /\{(\w+)\}/g;

/**
 * Replace `{name}` placeholders with their value.
 *
 * A placeholder with no matching param is left verbatim rather than blanked —
 * a visible `{percent}` in production is a bug report; a silent `off` is not.
 */
export function format(template: string, params: CopyParams = {}): string {
  return template.replace(PLACEHOLDER, (match, key: string) => {
    const value = params[key];
    return value === undefined ? match : String(value);
  });
}

/**
 * Format a date-only ISO string (`YYYY-MM-DD`, as validated by
 * `config/schema.ts`) or a `Date` as a long localised date.
 *
 * Date-only input is pinned to UTC so a reader in Lagos and one in Auckland
 * see the same day — the value is a calendar date, not an instant.
 *
 * An unparseable value degrades to itself: the expiry is still *stated*, it is
 * just not reformatted. (Build-time validation should make this unreachable.)
 */
export function formatDate(
  value: string | Date,
  options: Intl.DateTimeFormatOptions = { dateStyle: "long" },
  locale: string = DEFAULT_LOCALE,
): string {
  const date =
    typeof value === "string" ? new Date(`${value}T00:00:00Z`) : value;
  if (Number.isNaN(date.getTime())) return typeof value === "string" ? value : "";

  return new Intl.DateTimeFormat(locale, { timeZone: "UTC", ...options }).format(
    date,
  );
}

/**
 * Four-digit year for the footer copyright. Uses `Intl` rather than
 * `getFullYear()` so the digits are locale-appropriate (e.g. `en-GB` vs a
 * locale that renders a different calendar).
 */
export function formatYear(
  value: Date = new Date(),
  locale: string = DEFAULT_LOCALE,
): string {
  return new Intl.DateTimeFormat(locale, { year: "numeric" }).format(value);
}
